if tz is not None:
    tz = groups[tz]
if tz == 'Z':
    tz = FixedTzOffset(0, 'UTC')
elif tz:
    tz = tz.strip()
    if tz.isupper():
        # TODO use the awesome python TZ module?
        pass
    else:
        sign = tz[0]
        if ':' in tz:
            tzh, tzm = tz[1:].split(':')
        elif len(tz) == 4:  # 'snnn' format like '-530' for -5:30
            tzh, tzm = tz[1], tz[2:4]
        else:  # 'snnnn' format like '+0530' for +5:30
            tzh, tzm = tz[1:3], tz[3:5]
        offset = int(tzh) * 60 + int(tzm)
        if sign == '-':
            offset = -offset
        tz = FixedTzOffset(offset, tz)

